        {
            string code = null;
            string message = null;
            string target = null;
            ResponseInnerError innerError = null;
            IReadOnlyList<ResponseError> details = null;

            if (root.TryGetProperty("code", out var codeProp))
                code = codeProp.GetString();
            if (root.TryGetProperty("message", out var msgProp))
                message = msgProp.GetString();
            if (root.TryGetProperty("target", out var targetProp))
                target = targetProp.GetString();
            if (root.TryGetProperty("innererror", out var innerProp))
                innerError = ReadInnerError(innerProp);
            if (root.TryGetProperty("details", out var detailsProp) && detailsProp.ValueKind == JsonValueKind.Array)
            {
                var list = new List<ResponseError>();
                foreach (var item in detailsProp.EnumerateArray())
                {
                    list.Add(ReadFromElement(item));
                }
                details = list;
            }

            return new ResponseError(code, message, target, default, innerError, details);
        }

